insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"wh_questions_homework_q01_finish","speaker_external_id":"Ghost","source_path":"_registry\\dialogues\\wh_questions_homework.yaml","source_metadata":{}},{"key":"wh_questions_homework_q01_start","speaker_external_id":"Ghost","source_path":"_registry\\dialogues\\wh_questions_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"wh_questions_homework_q01_finish","locale":"he","line_order":0,"content":"המחברת מלאה בשאלות טובות. עכשיו אני כבר לא מפחדת לשכוח.","line_format":"plain_text"},{"dialogue_key":"wh_questions_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: What = מה, על דבר. Where = איפה, על מקום. When = מתי, על זמן.","line_format":"plain_text"},{"dialogue_key":"wh_questions_homework_q01_finish","locale":"he","line_order":2,"content":"Who = מי, על אדם. Why = למה, על סיבה. How = איך, על הדרך שבה משהו קורה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_homework_q01_finish","locale":"he","line_order":3,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"wh_questions_homework_q01_start","locale":"he","line_order":0,"content":"חזרתם. בזכותכם אני זוכרת את השם שלי ואת הלילה של הסערה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_homework_q01_start","locale":"he","line_order":1,"content":"עכשיו אני כותבת מחברת שאלות, כדי שלא אשכח שוב אף פעם.","line_format":"plain_text"},{"dialogue_key":"wh_questions_homework_q01_start","locale":"he","line_order":2,"content":"היום אין מילים חדשות. תראו לי לבד שאתם זוכרים את כל מילות השאלה.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
